@layer component {
  .appShell {
    --size: 4rem;

    display: grid;
    grid-template-rows: var(--size) 1fr;
    grid-template-columns: var(--sidebar-width) 1fr;
    background-color: var(--c-bg);
    height: 100dvh;
    overflow: hidden;
    color: var(--c-text);

    &:is(.open, :has(.sidebarWrapper:focus-within)) .sidebarWrapper {
      border-radius: var(--radius-alt);
    }

    &.closed:not(:has(.sidebarWrapper:focus-within)) {
      grid-template-columns: var(--size) 1fr;

      .sidebarHeader,
      .sidebarFooter {
        display: none;
      }

      .navHeader,
      .navItem {
        justify-content: center;

        .navLabel {
          display: none;
        }
      }
    }

    .skipLink {
      position: absolute;
      top: -10rem;
      left: 50%;
      transform: translateX(-50%);
      z-index: 100;
      border-radius: var(--radius);
      background-color: var(--c-text);
      padding: 0.5rem 1rem;
      color: var(--c-bg);
      font-weight: 600;
      text-decoration: none;

      &:focus {
        top: 0.75rem;
      }
    }

    .headerWrapper {
      display: flex;
      grid-row: 1 / 2;
      grid-column: 1 / -1;
      align-items: center;
      gap: 0.625rem;
      z-index: 20;
      border-bottom: 0.125rem solid var(--c-border);
      border-radius: var(--radius);
      border-top-right-radius: 0;
      border-top-left-radius: 0;
      background-color: var(--c-muted);
      padding: 0 1.5rem 0 0.625rem;

      .headerLink {
        cursor: auto;
        margin-left: 0.5rem;
        text-decoration: none;

        .header {
          color: var(--c-text);
          font-weight: 900;
          font-size: 1.75rem;
          line-height: 2.25rem;
          letter-spacing: -0.025em;
        }
      }

      .action {
        margin-left: auto;
      }
    }

    .sidebarWrapper {
      display: flex;
      grid-column: 1 / 2;
      flex-direction: column;
      border-right: 0.125rem solid var(--c-border);
      border-radius: var(--radius);
      border-top-left-radius: 0 !important;
      border-bottom-left-radius: 0 !important;
      background-color: color-mix(in oklch, var(--c-muted), var(--c-bg));
      overflow: hidden;

      .sidebarHeader,
      .sidebarFooter {
        flex-shrink: 0;
        border-radius: var(--radius-alt);
        max-height: 25%;
        overflow-y: auto;
      }
      .sidebarHeader {
        border-bottom: 0.125rem solid var(--c-border);
        padding: 0.75rem;
        font-weight: 800;
        font-size: 1.25rem;
        line-height: 1.75rem;
        letter-spacing: -0.025em;
      }
      .sidebarFooter {
        border-top: 0.125rem solid var(--c-border);

        &:not(.navWrapper) {
          padding: 0.5rem;
        }
      }

      .sidebar {
        flex: 1;
        min-height: 0;
        overflow-y: auto;
      }

      .navWrapper {
        display: flex;
        flex-direction: column;
        padding: 0.5rem 0;

        .navHeader,
        .navItem {
          display: flex;
          align-items: center;
          gap: 1rem;
          border-radius: var(--radius);
        }

        .navHeader {
          padding: 0.5rem 1rem 0.25rem 0.5rem;
          font-weight: 700;
          font-size: 1.25rem;
          letter-spacing: -0.025em;

          &:not(:first-child) {
            margin-top: 0.5rem;
            border-top: 0.125rem solid var(--c-border);
          }

          .navLabel {
            font-size: 1em;
          }
        }

        .navItem {
          cursor: pointer;
          border: none;
          background-color: transparent;
          padding: 0.75rem;
          color: inherit;
          color: var(--c-text);
          text-decoration: none;
          white-space: nowrap;

          &:hover {
            background-color: var(--c-muted);
          }

          &.active {
            border-radius: var(--radius-alt);
            background-color: var(--c-primary);

            &:hover {
              background-color: color-mix(in oklch, var(--c-primary) 75%, var(--c-muted));
            }
          }
        }
      }
    }

    .backdrop {
      display: none;
    }

    .main {
      grid-row: 2 / -1;
      grid-column: 2 / 3;
      padding: 1rem;
      overflow: auto;

      &:focus {
        outline: none;
      }

      .narrow {
        margin: 0 auto;
        max-width: 64rem;
      }
    }

    @media (max-width: 768px) {
      grid-template-columns: 1fr;

      &:is(.open, :has(.sidebarWrapper:focus-within)) {
        .sidebarWrapper {
          transform: translateX(0);
        }

        .backdrop {
          display: block;
          position: fixed;
          z-index: 5;
          backdrop-filter: blur(2px);
          inset: var(--size) 0 0 0;
          background-color: color-mix(in oklch, var(--c-bg) 75%, transparent);
        }
      }

      &.closed:not(:has(.sidebarWrapper:focus-within)) .sidebarWrapper {
        box-shadow: none;
      }

      .sidebarWrapper {
        position: fixed;
        top: var(--size);
        bottom: 0;
        left: 0;
        transform: translateX(-99%); /* Show just a bit */
        z-index: 10;
        width: var(--sidebar-width);
      }

      .main {
        grid-row: 2 / -1;
        grid-column: 1 / -1;
      }
    }
  }
}

import { useCachedStyles } from '@/hook/useCachedStyles';
import { cn, getCommonProps, type CommonProps } from '@/lib/utils';
import commonClasses from '@/style/common.module.css';
import { Button } from '@/ui/button/button';
import { Icon, menu } from '@/ui/icon/icon';
import { useId, useState, type CSSProperties, type HTMLAttributeAnchorTarget, type ReactNode } from 'react';
import { Link, useLocation } from 'wouter';
import classes from './appShell.module.css';

interface NavHeader {
  type: 'header';
  iconPath?: string;
  label: string;
}
interface NavItem {
  type?: 'item';
  iconPath: string;
  label: string;
  href: string;
  target?: HTMLAttributeAnchorTarget;
}
type Nav = NavHeader | NavItem;
type ContentOrNav = ReactNode | Nav[];
function isNav(nav: ContentOrNav): nav is Nav[] {
  return Array.isArray(nav) && nav.length > 0 && 'label' in nav[0];
}

const LINK_CLASSES = `${commonClasses.focusable} ${classes.navItem}`;
function NavLink({ label, iconPath, href, target }: NavItem) {
  const [path] = useLocation();
  const cStyles = useCachedStyles();

  const Comp = href.startsWith('http') ? 'a' : Link;

  return (
    <Comp
      className={cn(LINK_CLASSES, path === href && classes.active)}
      title={label}
      href={href}
      target={target}
      style={cStyles}
    >
      <Icon path={iconPath} />
      <span className={classes.navLabel}>{label}</span>
    </Comp>
  );
}

function SidebarNav({ className, children }: { className?: string; children: ContentOrNav }) {
  const isNavChildren = isNav(children);
  return (
    <div className={cn(className, isNavChildren && classes.navWrapper)}>
      {isNavChildren
        ? children.map(c => {
            if (c.type === 'header')
              return (
                <div key={c.label} className={classes.navHeader}>
                  {c.iconPath && <Icon path={c.iconPath} />}
                  <h3 className={classes.navLabel}>{c.label}</h3>
                </div>
              );

            return <NavLink key={c.label} {...c} />;
          })
        : children}
    </div>
  );
}

const SKIP_LINK_CLASSES = `${commonClasses.focusable} ${classes.skipLink}`,
  HEADER_CLASSES = `${commonClasses.shadow} ${classes.headerWrapper}`,
  SIDEBAR_CLASSES = `${commonClasses.shadow} ${classes.sidebarWrapper}`;
export function AppShell({
  header,
  action,
  sidebar,
  sidebarHeader,
  sidebarFooter,
  sidebarWidth = '16rem',
  wideMain,
  style,
  children,
  ...props
}: CommonProps<
  'div',
  {
    header: string;
    action?: ReactNode;
    sidebar: ContentOrNav;
    sidebarHeader?: string;
    sidebarFooter?: ContentOrNav;
    sidebarWidth?: CSSProperties['width'];
    wideMain?: boolean;
  }
>) {
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => window && window.innerWidth > 768);

  const cStyles = useCachedStyles();
  const id = useId();

  return (
    <div
      style={{ ...cStyles, ...style, '--sidebar-width': sidebarWidth } as CSSProperties} // used by children
      {...getCommonProps(props, classes.appShell, isSidebarOpen ? classes.open : classes.closed)}
    >
      <a className={SKIP_LINK_CLASSES} href={`#${id}-main`}>
        Skip to main content
      </a>

      <header className={HEADER_CLASSES}>
        <Button
          size='icon'
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          variant={isSidebarOpen ? 'primary' : 'secondary'}
          aria-label='Toggle Sidebar'
          aria-controls={`${id}-sidebar`}
          aria-expanded={isSidebarOpen}
        >
          <Icon path={menu} />
        </Button>
        <Link className={classes.headerLink} href='/'>
          <h1 className={classes.header}>{header}</h1>
        </Link>
        {action && <div className={classes.action}>{action}</div>}
      </header>

      <aside id={`${id}-sidebar`} className={SIDEBAR_CLASSES}>
        {sidebarHeader && <h2 className={classes.sidebarHeader}>{sidebarHeader}</h2>}
        <SidebarNav className={classes.sidebar}>{sidebar}</SidebarNav>
        {sidebarFooter && <SidebarNav className={classes.sidebarFooter}>{sidebarFooter}</SidebarNav>}
      </aside>

      <div className={classes.backdrop} onClick={() => setIsSidebarOpen(false)} aria-hidden='true' />

      <main id={`${id}-main`} className={classes.main} tabIndex={-1}>
        {wideMain ? children : <div className={classes.narrow}>{children}</div>}
      </main>
    </div>
  );
}
